<script>
var DC_AJAX_URL = <?php echo wp_json_encode( admin_url( 'admin-ajax.php' ) ); ?>;
var DC_NONCE = <?php echo wp_json_encode( wp_create_nonce( 'po_denuncia' ) ); ?>;
</script>
<script>
(function(){
  try{
    var micBtn = document.getElementById('mic-btn'), micStatus = document.getElementById('mic-status');
    var relatoTexto = document.getElementById('relato-texto');
    var SpeechRec = window.SpeechRecognition || window.webkitSpeechRecognition;
    var reconhecedor = null, ouvindo = false, textoBase = '';

    if (!SpeechRec) {
      micBtn.hidden = true;
      micStatus.textContent = 'ditado por voz não funciona neste navegador — pode escrever direto aqui';
    } else {
      micBtn.addEventListener('click', function(){
        if (ouvindo) { reconhecedor.stop(); return; }
        textoBase = relatoTexto.value ? relatoTexto.value.replace(/\s+$/, '') + ' ' : '';
        micStatus.classList.remove('erro');
        reconhecedor = new SpeechRec();
        reconhecedor.lang = 'pt-BR';
        reconhecedor.continuous = true;
        reconhecedor.interimResults = true;
        reconhecedor.addEventListener('start', function(){
          ouvindo = true;
          micBtn.classList.add('on');
          micStatus.textContent = 'ouvindo… toque de novo pra parar';
        });
        reconhecedor.addEventListener('result', function(e){
          var finalTxt = '', interim = '';
          for (var i = 0; i < e.results.length; i++){
            var t = e.results[i][0].transcript;
            if (e.results[i].isFinal) finalTxt += t + ' '; else interim += t;
          }
          relatoTexto.value = textoBase + finalTxt + interim;
        });
        reconhecedor.addEventListener('end', function(){
          ouvindo = false;
          micBtn.classList.remove('on');
          micStatus.textContent = 'toque no microfone pra falar de novo, se quiser';
          textoBase = relatoTexto.value;
        });
        reconhecedor.addEventListener('error', function(e){
          ouvindo = false;
          micBtn.classList.remove('on');
          micStatus.classList.add('erro');
          micStatus.textContent = (e.error === 'not-allowed' || e.error === 'service-not-allowed')
            ? 'sem permissão pro microfone — pode escrever direto aqui'
            : 'não deu pra ouvir agora — pode escrever direto aqui';
        });
        try { reconhecedor.start(); }
        catch(err){ micStatus.classList.add('erro'); micStatus.textContent = 'não deu pra iniciar — tenta de novo'; }
      });
    }

    var drop = document.getElementById('drop'), fileInput = document.getElementById('file-input'), fileList = document.getElementById('file-list');
    var files = [];
    function renderFiles(){
      fileList.innerHTML = '';
      files.forEach(function(f, i){
        var row = document.createElement('div');
        row.className = 'file-row';
        var nm = document.createElement('span'); nm.className = 'nm'; nm.textContent = f.name;
        var btn = document.createElement('button'); btn.type = 'button'; btn.textContent = '✕'; btn.setAttribute('aria-label','remover');
        btn.addEventListener('click', function(){ files.splice(i,1); renderFiles(); });
        row.appendChild(nm); row.appendChild(btn);
        fileList.appendChild(row);
      });
    }
    drop.addEventListener('click', function(){ fileInput.click(); });
    fileInput.addEventListener('change', function(){
      Array.prototype.forEach.call(fileInput.files, function(f){ files.push(f); });
      renderFiles();
    });
    ['dragover','dragenter'].forEach(function(ev){
      drop.addEventListener(ev, function(e){ e.preventDefault(); drop.classList.add('over'); });
    });
    ['dragleave','drop'].forEach(function(ev){
      drop.addEventListener(ev, function(e){ e.preventDefault(); drop.classList.remove('over'); });
    });
    drop.addEventListener('drop', function(e){
      if (e.dataTransfer && e.dataTransfer.files){
        Array.prototype.forEach.call(e.dataTransfer.files, function(f){ files.push(f); });
        renderFiles();
      }
    });

    var idCredito = document.getElementById('id-credito'), idAnonimo = document.getElementById('id-anonimo');
    var creditoFields = document.getElementById('credito-fields');
    function syncId(){ creditoFields.classList.toggle('show', idCredito.checked); }
    idCredito.addEventListener('change', syncId);
    idAnonimo.addEventListener('change', syncId);

    var form = document.getElementById('tip-form'), done = document.getElementById('done');
    var novoEnvio = document.getElementById('novo-envio'), erroEnvio = document.getElementById('erro-envio');
    var submitBtn = form.querySelector('.submit');
    var protocoloEl = document.getElementById('protocolo-num');

    form.addEventListener('submit', function(e){
      e.preventDefault();
      erroEnvio.hidden = true;

      var relato = relatoTexto.value.trim();
      if (!relato && files.length === 0){
        erroEnvio.textContent = 'Escreva (ou fale) o relato, ou envie uma foto/vídeo antes de enviar.';
        erroEnvio.hidden = false;
        window.scrollTo({ top: form.offsetTop - 70, behavior: 'smooth' });
        return;
      }

      var fd = new FormData();
      fd.append('action', 'po_denuncia_submit');
      fd.append('nonce', DC_NONCE);
      fd.append('relato', relato);
      fd.append('local', document.getElementById('local').value.trim());
      fd.append('identidade', idCredito.checked ? 'credito' : 'anonimo');
      fd.append('nome', document.getElementById('nome').value.trim());
      fd.append('insta', document.getElementById('insta').value.trim());
      fd.append('site_web', document.getElementById('site_web').value);
      files.forEach(function(f){ fd.append('midia[]', f, f.name); });

      submitBtn.disabled = true;
      submitBtn.textContent = 'Enviando…';

      fetch(DC_AJAX_URL, { method: 'POST', body: fd })
        .then(function(r){ return r.json(); })
        .then(function(res){
          submitBtn.disabled = false;
          submitBtn.textContent = 'Enviar';
          if (res && res.success){
            protocoloEl.textContent = 'Protocolo ' + res.data.protocolo;
            form.style.display = 'none';
            done.classList.add('show');
            window.scrollTo({top:0, behavior:'smooth'});
          } else {
            erroEnvio.textContent = (res && res.data && res.data.mensagem) ? res.data.mensagem : 'Não deu pra enviar agora, tenta de novo em alguns minutos.';
            erroEnvio.hidden = false;
          }
        })
        .catch(function(){
          submitBtn.disabled = false;
          submitBtn.textContent = 'Enviar';
          erroEnvio.textContent = 'Sem conexão no momento — tenta de novo em alguns minutos.';
          erroEnvio.hidden = false;
        });
    });

    novoEnvio.addEventListener('click', function(){
      form.reset();
      files = []; renderFiles();
      if (ouvindo && reconhecedor) reconhecedor.stop();
      micStatus.classList.remove('erro');
      if (SpeechRec) micStatus.textContent = 'toque no microfone pra falar em vez de escrever';
      syncId();
      form.style.display = '';
      done.classList.remove('show');
    });

    syncId();
  }catch(err){ console.error(err); }
})();
</script>

<script>
/* trava o zoom de verdade: o navegador ignora a tag da página para o gesto de
   beliscar, então bloqueamos o próprio gesto aqui (padrão usado em apps). */
(function(){
  document.addEventListener('gesturestart', function (e) { e.preventDefault(); }, { passive: false });
  document.addEventListener('gesturechange', function (e) { e.preventDefault(); }, { passive: false });
  document.addEventListener('gestureend', function (e) { e.preventDefault(); }, { passive: false });
  document.addEventListener('touchmove', function (e) {
    if (e.touches.length > 1) e.preventDefault();
  }, { passive: false });
  var ultimoToque = 0;
  document.addEventListener('touchend', function (e) {
    var agora = Date.now();
    if (agora - ultimoToque <= 300) e.preventDefault();
    ultimoToque = agora;
  }, { passive: false });
})();
</script>

